// ---------------------------------------------------------------------------
// Library: resources (books, articles, docs, links) and highlights
// ---------------------------------------------------------------------------

export const resources = pgTable(
  'resources',
  {
    id: id(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    type: resourceType('type').notNull(),
    title: text('title').notNull(),
    authors: text('authors')
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    url: text('url'),
    description: text('description'),
    coverAssetId: uuid('cover_asset_id'),
    status: readingStatus('status').notNull().default('want_to_read'),
    startedOn: date('started_on'),
    finishedOn: date('finished_on'),
    /** Personal rating, 1–5. */
    rating: smallint('rating'),
    /** Reading progress, 0–100. */
    progress: smallint('progress'),
    createdBy: uuid('created_by').references(() => users.id, {
      onDelete: 'set null',
    }),
    archivedAt: timestamptz('archived_at'),
    deletedAt: timestamptz('deleted_at'),
    ...timestamps,
  },
  (t) => [
    unique('resources_workspace_id_key').on(t.workspaceId, t.id),
    // Cover must be an asset of the same workspace. Clear the reference before deleting the asset.
    foreignKey({
      name: 'resources_cover_asset_fk',
      columns: [t.workspaceId, t.coverAssetId],
      foreignColumns: [assets.workspaceId, assets.id],
    }),
    check('resources_rating_check', sql`${t.rating} between 1 and 5`),
    check('resources_progress_check', sql`${t.progress} between 0 and 100`),
    check(
      'resources_dates_check',
      sql`${t.finishedOn} is null or ${t.startedOn} is null or ${t.finishedOn} >= ${t.startedOn}`,
    ),
    // Library tabs: type + status, most recently touched first.
    index('resources_library_idx')
      .on(t.workspaceId, t.type, t.status, t.updatedAt.desc())
      .where(sql`${t.deletedAt} is null`),
  ],
);

/** Book-only fields, one row per book resource. */
export const bookDetails = pgTable(
  'book_details',
  {
    resourceId: uuid('resource_id')
      .primaryKey()
      .references(() => resources.id, { onDelete: 'cascade' }),
    isbn: text('isbn'),
    publisher: text('publisher'),
    publishedYear: smallint('published_year'),
    pageCount: integer('page_count'),
    currentPage: integer('current_page'),
  },
  (t) => [
    check(
      'book_details_page_count_check',
      sql`${t.pageCount} is null or ${t.pageCount} > 0`,
    ),
    check(
      'book_details_current_page_check',
      sql`${t.currentPage} is null or ${t.currentPage} >= 0`,
    ),
  ],
);

export const highlights = pgTable(
  'highlights',
  {
    id: id(),
    workspaceId: uuid('workspace_id').notNull(),
    resourceId: uuid('resource_id').notNull(),
    text: text('text').notNull(),
    note: text('note'),
    chapter: text('chapter'),
    pageNumber: integer('page_number'),
    /** Reader-specific location (e-book CFI, timestamp in a video…). */
    location: jsonb('location'),
    color: text('color'),
    createdBy: uuid('created_by').references(() => users.id, {
      onDelete: 'set null',
    }),
    ...timestamps,
  },
  (t) => [
    unique('highlights_workspace_id_key').on(t.workspaceId, t.id),
    foreignKey({
      name: 'highlights_resource_fk',
      columns: [t.workspaceId, t.resourceId],
      foreignColumns: [resources.workspaceId, resources.id],
    }).onDelete('cascade'),
    index('highlights_resource_idx').on(t.resourceId, t.createdAt),
    index('highlights_recent_idx').on(t.workspaceId, t.createdAt.desc()),
  ],
);

/** Highlights linked to pages ("→ Consistent hashing"). */
export const highlightLinks = pgTable(
  'highlight_links',
  {
    workspaceId: uuid('workspace_id').notNull(),
    highlightId: uuid('highlight_id').notNull(),
    pageId: uuid('page_id').notNull(),
    createdAt: timestamptz('created_at').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.highlightId, t.pageId] }),
    foreignKey({
      name: 'highlight_links_highlight_fk',
      columns: [t.workspaceId, t.highlightId],
      foreignColumns: [highlights.workspaceId, highlights.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'highlight_links_page_fk',
      columns: [t.workspaceId, t.pageId],
      foreignColumns: [pages.workspaceId, pages.id],
    }).onDelete('cascade'),
    index('highlight_links_page_idx').on(t.pageId),
  ],
);

// ---------------------------------------------------------------------------
// Learning journal
// ---------------------------------------------------------------------------

export const journalEntries = pgTable(
  'journal_entries',
  {
    id: id(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    /** Author. Entries are personal even inside a team workspace. */
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** The calendar day the entry is about, in the author's time zone. */
    entryDate: date('entry_date').notNull(),
    title: text('title').notNull().default(''),
    learned: text('learned').notNull().default(''),
    challenges: text('challenges').notNull().default(''),
    reflection: text('reflection').notNull().default(''),
    ...timestamps,
  },
  (t) => [
    unique('journal_entries_workspace_id_key').on(t.workspaceId, t.id),
    // One entry per person per day; also serves the week-strip date range query.
    unique('journal_entries_one_per_day').on(
      t.workspaceId,
      t.userId,
      t.entryDate,
    ),
  ],
);

