export const collectionResources = pgTable(
  'collection_resources',
  {
    workspaceId: uuid('workspace_id').notNull(),
    collectionId: uuid('collection_id').notNull(),
    resourceId: uuid('resource_id').notNull(),
    addedAt: timestamptz('added_at').notNull().defaultNow(),
  },
  (t) => [
    primaryKey({ columns: [t.collectionId, t.resourceId] }),
    foreignKey({
      name: 'collection_resources_collection_fk',
      columns: [t.workspaceId, t.collectionId],
      foreignColumns: [collections.workspaceId, collections.id],
    }).onDelete('cascade'),
    foreignKey({
      name: 'collection_resources_resource_fk',
      columns: [t.workspaceId, t.resourceId],
      foreignColumns: [resources.workspaceId, resources.id],
    }).onDelete('cascade'),
    index('collection_resources_resource_idx').on(t.resourceId),
  ],
);

// ---------------------------------------------------------------------------
// Search
// ---------------------------------------------------------------------------

/**
 * One row per searchable item, written by the owning service in the same transaction as the item.
 * A single GIN index serves the global Search screen across all content types, with filters on
 * type, tags and collections. `entity_id` is not a foreign key (it points at different tables), so
 * services must delete the row when they hard-delete the item.
 */
export const searchDocuments = pgTable(
  'search_documents',
  {
    id: id(),
    workspaceId: uuid('workspace_id')
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    entityType: searchEntityType('entity_type').notNull(),
    entityId: uuid('entity_id').notNull(),
    title: text('title').notNull().default(''),
    body: text('body').notNull().default(''),
    tagIds: uuid('tag_ids')
      .array()
      .notNull()
      .default(sql`'{}'::uuid[]`),
    collectionIds: uuid('collection_ids')
      .array()
      .notNull()
      .default(sql`'{}'::uuid[]`),
    /** Title matches rank above body matches. English stemming, so "hash" also finds "hashing". */
    searchVector: tsvector('search_vector')
      .notNull()
      .generatedAlwaysAs(
        sql`setweight(to_tsvector('english', coalesce("title", '')), 'A') || setweight(to_tsvector('english', coalesce("body", '')), 'B')`,
      ),
    updatedAt: timestamptz('updated_at')
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    unique('search_documents_entity_key').on(t.entityType, t.entityId),
    index('search_documents_vector_idx').using('gin', t.searchVector),
    index('search_documents_tags_idx').using('gin', t.tagIds),
    index('search_documents_collections_idx').using('gin', t.collectionIds),
    index('search_documents_workspace_type_idx').on(
      t.workspaceId,
      t.entityType,
    ),
  ],
);
